SourceCode.Declaration:
/// <summary>
/// Sends a generic "business event triggered" signal to Application Insights.
/// Called from the BusinessEventsCommitLog inserted event, so it covers all
/// activated business events without per-event code.
/// </summary>
/// <remarks>
/// Runs inside the caller's transaction. Do not add database access, lookups
/// or try/catch here: exceptions inside a transaction are not caught and would
/// fail the business process. Never log SerializedContract (business data).
/// </remarks>
internal final class METBusinessEventTelemetryHelper
{
    private const str TelemetryEventId     = 'METBE001';
    private const str TriggerTypePublished = 'Published';
    private const str TriggerTypeResent    = 'Resent';

}

Method.Source:
/// <summary>
/// Logs a business event commit log entry to Application Insights.
/// </summary>
/// <param name = "_commitLog">The inserted commit log record.</param>
internal static void logBusinessEventTriggered(BusinessEventsCommitLog _commitLog)
{
    if (!_commitLog || !_commitLog.BusinessEventId)
    {
        return;
    }

    SysApplicationInsightsComplianceDataType dataType = SysApplicationInsightsComplianceDataType::CustomerContent;

    // Rows written by the publisher have no endpoint.
    // Rows moved back from the exception log (resend) carry the failed endpoint.
    str triggerType = _commitLog.TargetEndpoint ? TriggerTypeResent : TriggerTypePublished;

    SysApplicationInsightsEventTelemetry eventTelemetry =
        SysApplicationInsightsEventTelemetry::newFromEventIdName(
            TelemetryEventId,
            METTelemetryEventNames::BusinessEventTriggered);

    eventTelemetry.addProperty(ISMTelemetryProperty::construct('BusinessEventId', _commitLog.BusinessEventId,           dataType));
    eventTelemetry.addProperty(ISMTelemetryProperty::construct('EventInstanceId', _commitLog.EventId,                   dataType));
    eventTelemetry.addProperty(ISMTelemetryProperty::construct('LegalEntity',     _commitLog.LegalEntity,               dataType));
    eventTelemetry.addProperty(ISMTelemetryProperty::construct('TriggerType',     triggerType,                          dataType));
    eventTelemetry.addProperty(ISMTelemetryProperty::construct('TargetEndpoint',  int642Str(_commitLog.TargetEndpoint), dataType));
    eventTelemetry.addProperty(ISMTelemetryProperty::construct('UserId',          curUserId(),                          dataType));
    eventTelemetry.addProperty(ISMTelemetryProperty::construct('TtsLevel',        int2Str(appl.ttsLevel()),             dataType));

    SysApplicationInsightsTelemetryLogger::instance().trackEvent(eventTelemetry);
}
